def _recover_tridiagonal_basis_n1024(vectors, values):
    batch, n, _ = vectors.shape
    scale = values.abs().amax(dim=1)
    threshold = 64.0 * torch.finfo(values.dtype).eps * (1.0 + scale)
    joined = (values[:, 1:] - values[:, :-1]).abs() <= threshold[:, None]
    buckets = {}
    for matrix, links in enumerate(joined.cpu().tolist()):
        start = 0
        for gap, connected in enumerate(links):
            if connected:
                continue
            width = gap + 1 - start
            if width >= 16:
                buckets.setdefault(width, []).append((matrix, start))
            start = gap + 1
        width = n - start
        if width >= 16:
            buckets.setdefault(width, []).append((matrix, start))

    if not buckets:
        return vectors
    recovered = vectors.clone()
    rows = torch.arange(n, device=vectors.device)
    for width, ranges in buckets.items():
        matrices = torch.tensor(
            [item[0] for item in ranges], device=vectors.device
        )
        starts = torch.tensor(
            [item[1] for item in ranges], device=vectors.device
        )
        columns = starts[:, None] + torch.arange(width, device=vectors.device)
        blocks = vectors[
            matrices[:, None, None], rows[None, :, None], columns[:, None, :]
        ]
        q, _ = torch.linalg.qr(blocks, mode="reduced")
        recovered[
            matrices[:, None, None], rows[None, :, None], columns[:, None, :]
        ] = q
    return recovered.contiguous()


