              values.is_cuda() && vectors.is_cuda(),
              "tridiagonal refinement inputs must be CUDA tensors");
  TORCH_CHECK(diagonal.scalar_type() == torch::kFloat32 &&
              off_diagonal.scalar_type() == torch::kFloat32 &&
              values.scalar_type() == torch::kFloat32 &&
              vectors.scalar_type() == torch::kFloat32,
              "tridiagonal refinement inputs must be FP32");
  TORCH_CHECK(diagonal.is_contiguous() && off_diagonal.is_contiguous() &&
              values.is_contiguous() && vectors.is_contiguous(),
              "tridiagonal refinement inputs must be contiguous");
  TORCH_CHECK(vectors.dim() == 3 && vectors.size(1) == 1024 &&
              vectors.size(2) == 1024,
              "tridiagonal refinement requires n=1024");
  const c10::cuda::CUDAGuard device_guard(vectors.device());
  constexpr int kN = 1024;
  constexpr int kEigenpairs = 26;
  constexpr int kVectorPitch = 27;
  const int batch = static_cast<int>(vectors.size(0));
  const int solve_shared =
      (2 * kN + 2 * kN * kVectorPitch) * sizeof(float);
  cudaFuncSetAttribute(
      tridiagonal_inverse_iteration<
          kEigenpairs, kVectorPitch, kN, true>,
      cudaFuncAttributeMaxDynamicSharedMemorySize, solve_shared);
