__device__ __forceinline__ float block_sum_leader(
    float value, float* warp_sums) {
  for (int offset = 16; offset > 0; offset >>= 1) {
    value += __shfl_down_sync(0xffffffff, value, offset);
  }
  const int lane = static_cast<int>(threadIdx.x) & 31;
  const int warp = static_cast<int>(threadIdx.x) >> 5;
  if (lane == 0) {
    warp_sums[warp] = value;
  }
  __syncthreads();
  if (warp == 0) {
    value = lane < (static_cast<int>(blockDim.x) + 31) / 32
        ? warp_sums[lane]
        : 0.0f;
    for (int offset = 16; offset > 0; offset >>= 1) {
      value += __shfl_down_sync(0xffffffff, value, offset);
    }
  }
  return value;
}

__global__ void dense_batch_n1024_kernel(
    const float* __restrict__ input, int* __restrict__ flag, int batch) {
  constexpr int n = 1024;
  __shared__ float warp_sums[4];
  __shared__ int dense;
  const int tid = static_cast<int>(threadIdx.x);
  if (tid == 0) {
    dense = 1;
  }
  __syncthreads();

  for (int matrix = 0; matrix < batch; ++matrix) {
    const int64_t matrix_offset = static_cast<int64_t>(matrix) * n * n;
    float absolute_sum = 0.0f;
    float square_sum = 0.0f;
    for (int index = tid; index < n; index += blockDim.x) {
      const float value = input[matrix_offset + index * (n + 1)];
      absolute_sum += fabsf(value);
      square_sum += value * value;
    }
